// Start time pehle node se lein ya current time use karein
let startTime = Date.now();
let existingLogs = [];
let userId = '';

try {
  const codeNodeData = $('Code in JavaScript').first().json;
  startTime = codeNodeData._start_time || startTime;
  existingLogs = codeNodeData._node_timestamps || [];
  userId = codeNodeData.user_id || '';
} catch (e) {
  // Fallback agar node reference na mile
}

const currentTime = Date.now();
const elapsedSec = ((currentTime - startTime) / 1000).toFixed(2);

const updatedLogs = [
  ...existingLogs,
  { node: "AI Agent Processing", time: `${elapsedSec}s` }
];

return [{
  json: {
    ...$json,
    user_id: userId,
    _start_time: startTime,
    _node_timestamps: updatedLogs
  }
}];

const now = Date.now();

return $input.all().flatMap(item => {
  // 1. Data handling
  const payload = item.json.body || item.json;
  const entry = payload?.entry?.[0];
  const changes = entry?.changes?.[0]?.value;

  // Real IP extraction (Cloudflare / Nginx Reverse Proxy / Meta Fallback)
  const headers = $('Webhook1').first().json.headers || {};
  const ipAddress = headers['cf-connecting-ip'] || 
                    headers['x-forwarded-for']?.split(',')[0]?.trim() || 
                    headers['x-real-ip'] || 
                    '157.240.199.60';

  // 2. Status receipts drop
  if (!changes?.messages || changes.messages.length === 0) {
    return [];
  }

  const message = changes.messages[0];
  const contact = changes.contacts?.[0];

  let userText = '';
  let buttonId = '';

  // 3. Extract text / interactive clicks
  if (message.type === 'text') {
    userText = message.text?.body || '';
  } else if (message.type === 'interactive') {
    if (message.interactive?.type === 'button_reply') {
      buttonId = message.interactive.button_reply.id;
      userText = message.interactive.button_reply.title;
    } else if (message.interactive?.type === 'list_reply') {
      buttonId = message.interactive.list_reply.id;
      userText = message.interactive.list_reply.title;
    }
  }

  return {
    json: {
      is_valid_message: true,
      user_id: message.from,
      phone_number_id: changes.metadata?.phone_number_id || '',
      user_name: contact?.profile?.name || '',
      text: userText.trim(),
      button_id: buttonId,
      message_type: message.type,
      raw_message_id: message.id,
      ip_address: ipAddress, // Passed downstream
      _start_time: now,
      _node_timestamps: [{ node: "WhatsApp Webhook", time: "0.00s" }]
    }
  };
});

const staticData = $getWorkflowStaticData('global');

// 1. Data Extract from DB API
let rawInput = $input.first().json;
let masterCards = [];

if (rawInput.data && Array.isArray(rawInput.data)) {
  masterCards = rawInput.data;
} else if (Array.isArray(rawInput)) {
  masterCards = rawInput;
} else if ($json.data && Array.isArray($json.data)) {
  masterCards = $json.data;
} else {
  masterCards = $input.all().map(i => i.json);
}

// 2. User Filters Retrieve Karein
let userId = '';
let buttonId = '';
let filterFee = 'all';
let filterType = 'all';
let leadInfo = {};

try {
  const ifNode = $('If').first().json;
  userId = ifNode.user_id || '';
  buttonId = ifNode.button_id || '';
  filterFee = ifNode.fee_preference || 'all';
  filterType = ifNode.card_type || 'all';
  leadInfo = ifNode.lead_info || {};
} catch (e) {
  try {
    const js3Node = $('Code in JavaScript3').first().json;
    userId = js3Node.user_id || '';
    buttonId = js3Node.button_id || '';
    filterFee = js3Node.fee_preference || 'all';
    filterType = js3Node.card_type || 'all';
    leadInfo = js3Node.lead_info || {};
  } catch (err) {}
}

// Root node check for pagination or click
try {
  const rootNode = $('Code in JavaScript').first().json;
  if (rootNode.button_id && (rootNode.button_id.startsWith('card_page_') || rootNode.button_id.startsWith('apply_') || rootNode.button_id.startsWith('learn_more_'))) {
    buttonId = rootNode.button_id;
  }
  if (!userId) userId = rootNode.user_id || '';
} catch (err) {}

if (buttonId.startsWith('filter_')) {
  const parts = buttonId.split('_');
  if (parts.length >= 3) {
    filterFee = parts[1];
    filterType = parts[2];
  }
}

const cleanText = (val) => (!val ? '' : String(val).replace(/<[^>]*>?/gm, '').trim());

// ====================================================
// 💡 1. LEARN MORE HANDLER
// ====================================================
if (buttonId.startsWith('learn_more_')) {
  const targetId = buttonId.replace('learn_more_', '');
  const selectedCard = masterCards.find(c => String(c.id || c.uuid || c._id || '') === targetId) || (staticData.filteredCards && staticData.filteredCards[0]);

  if (selectedCard) {
    const cardFeatures = cleanText(selectedCard.reward_points || selectedCard.rewardPoints || selectedCard.features) || 'Complimentary reward points, lounge access & merchant discounts.';
    const cardTerms = cleanText(selectedCard.terms || selectedCard.terms_and_conditions || selectedCard.tnc) || 'Standard bank approval and KYC guidelines apply.';

    const detailsText = `ℹ️ *Detailed Card Information*\n\n` +
      `💳 *Card Name:* ${selectedCard.name || 'Credit Card'}\n` +
      `🏦 *Bank:* ${selectedCard.bank || 'Partner Bank'}\n\n` +
      `🎯 *Key Features:*\n${cardFeatures}\n\n` +
      `💵 *Fees & Charges:*\n` +
      `• Joining Fee: ₹${selectedCard.joining_fee ?? selectedCard.joiningFee ?? 'NIL'}\n` +
      `• Annual/Renewal Fee: ₹${selectedCard.annual_fee ?? selectedCard.renewal_fee ?? selectedCard.annualFee ?? 'NIL'}\n\n` +
      `📜 *Terms & Conditions:*\n${cardTerms}`;

    return [{
      json: {
        user_id: userId,
        type: "text",
        text: { preview_url: false, body: detailsText }
      }
    }];
  }
}

// ====================================================
// 💡 2. APPLY NOW HANDLER
// ====================================================
if (buttonId.startsWith('apply_')) {
  const targetId = buttonId.replace('apply_', '');
  const selectedCard = masterCards.find(c => String(c.id || c.uuid || c._id || '') === targetId) || (staticData.filteredCards && staticData.filteredCards[0]);

  const fullCardId = selectedCard ? String(selectedCard.id || selectedCard.uuid || selectedCard._id || targetId) : targetId;
  const cardName = selectedCard ? (selectedCard.name || 'Selected Card') : 'Credit Card';

  const finalLead = {
    cardId: fullCardId,
    card_name: cardName,
    applicant_name: leadInfo.name || 'Customer',
    applicant_phone: leadInfo.phone || userId.replace(/\D/g, '').slice(-10),
    applicant_email: leadInfo.email || `${userId}@finonest.in`
  };

  return [{
    json: {
      user_id: userId,
      is_lead_flow: true,
      is_final_submit: true,
      lead_complete: true,
      lead_info: finalLead
    }
  }];
}

// ====================================================
// 💡 3. STRICT CREDIT CARD ONLY FILTERING
// ====================================================
let currentIndex = 0;
let filteredCards = [];

if (buttonId.startsWith('card_page_')) {
  currentIndex = parseInt(buttonId.replace('card_page_', ''), 10) || 0;
  filteredCards = staticData.filteredCards || masterCards;
} else {
  // Step A: Loans aur non-credit products ko pehle hi bahar nikalna
  const onlyCreditCards = masterCards.filter(card => {
    const name = String(card.name || '').toLowerCase();
    const type = String(card.type || card.product_type || '').toLowerCase();

    // Reject loans
    if (name.includes('loan') || type.includes('loan') || name.includes('finance') || type.includes('personal_loan')) {
      return false;
    }

    // Status check
    const isActive = (card.status || 'active').toLowerCase() === 'active';
    return isActive;
  });

  // Step B: Category & Fee filter apply karna
  filteredCards = onlyCreditCards.filter(card => {
    const cardName = String(card.name || '').toLowerCase();
    const cardBank = String(card.bank || '').toLowerCase();
    const cardRewards = String(card.reward_points || card.rewardPoints || '').toLowerCase();
    const cardFeatures = String(card.features || '').toLowerCase();
    const combinedText = `${cardName} ${cardBank} ${cardRewards} ${cardFeatures}`;

    // Fee Filter
    const jFee = parseFloat(card.joining_fee ?? card.joiningFee ?? 0);
    const rFee = parseFloat(card.annual_fee ?? card.renewal_fee ?? card.annualFee ?? 0);
    const isFree = (jFee === 0 && rFee === 0) || combinedText.includes('lifetime free') || combinedText.includes('nil');

    if (filterFee === 'free' && !isFree) return false;
    if (filterFee === 'paid' && isFree) return false;

    // Benefit Type Matching
    if (filterType === 'lounge') return combinedText.includes('lounge') || combinedText.includes('airport');
    if (filterType === 'fuel') return combinedText.includes('fuel') || combinedText.includes('petrol') || combinedText.includes('bpcl') || combinedText.includes('hpcl') || combinedText.includes('surcharge') || combinedText.includes('indianoil');
    if (filterType === 'travel') return combinedText.includes('travel') || combinedText.includes('flight') || combinedText.includes('air') || combinedText.includes('indigo') || combinedText.includes('miles');
    if (filterType === 'dining') return combinedText.includes('dining') || combinedText.includes('food') || combinedText.includes('swiggy') || combinedText.includes('zomato');
    if (filterType === 'upi') return combinedText.includes('rupay') || combinedText.includes('upi');
    if (filterType === 'utility') return combinedText.includes('utility') || combinedText.includes('bill') || combinedText.includes('recharge');
    if (filterType === 'rewards') return combinedText.includes('reward') || combinedText.includes('point');
    if (filterType === 'shopping') return combinedText.includes('shopping') || combinedText.includes('cashback') || combinedText.includes('amazon') || combinedText.includes('flipkart');

    return true;
  });

  // Safe fallback (Agar specific benefit card na mile, toh sirf matching fee wale CREDIT CARDS dikhayein, loan nahi)
  if (filteredCards.length === 0) {
    filteredCards = onlyCreditCards.filter(card => {
      const jFee = parseFloat(card.joining_fee || 0);
      const rFee = parseFloat(card.annual_fee || 0);
      const isFree = (jFee === 0 && rFee === 0);
      return filterFee === 'free' ? isFree : !isFree;
    });
  }

  // Double fallback
  if (filteredCards.length === 0) {
    filteredCards = onlyCreditCards.slice(0, 5);
  }

  staticData.filteredCards = filteredCards;
  currentIndex = 0;
}

const totalCards = filteredCards.length;
if (currentIndex >= totalCards) currentIndex = 0;

const currentCard = filteredCards[currentIndex];
const cardId = String(currentCard.id || currentCard.uuid || currentCard._id || '0');
const nextIndex = (currentIndex + 1) % totalCards;

const cardTitle = `💳 *${currentCard.name || 'Credit Card'}*\n` +
  `🏦 *Bank:* ${currentCard.bank || 'Partner Bank'}\n\n` +
  `✨ *Features:* ${currentCard.reward_points || currentCard.rewardPoints || currentCard.features || 'Rewards & Benefits'}\n` +
  `💰 *Joining Fee:* ₹${currentCard.joining_fee ?? currentCard.joiningFee ?? '0'}\n` +
  `🔄 *Renewal Fee:* ₹${currentCard.annual_fee ?? currentCard.renewal_fee ?? currentCard.annualFee ?? '0'}\n\n` +
  `📄 *Card ${currentIndex + 1} of ${totalCards}*`;

const cardImageUrl = currentCard.image || currentCard.variant_image || currentCard.variantImage || '';

const buttons = [
  {
    type: "reply",
    reply: { id: `apply_${cardId}`, title: "✅ Apply Now" }
  },
  {
    type: "reply",
    reply: { id: `learn_more_${cardId}`, title: "ℹ️ Learn More" }
  }
];

if (totalCards > 1) {
  buttons.push({
    type: "reply",
    reply: { id: `card_page_${nextIndex}`, title: "Next ▶️" }
  });
}

return [{
  json: {
    user_id: userId,
    type: "interactive",
    interactive: {
      type: "button",
      ...(cardImageUrl ? {
        header: {
          type: "image",
          image: { link: cardImageUrl }
        }
      } : {}),
      body: { text: cardTitle },
      action: { buttons: buttons }
    }
  }
}];

const staticData = $getWorkflowStaticData('global');
staticData.userStates = staticData.userStates || {};

const userId = String($json.user_id || '').trim();
const userText = String($json.text || '').trim();
const buttonId = String($json.button_id || '').trim();
const lowerText = userText.toLowerCase();

let userState = staticData.userStates[userId] || {};

// 🧹 Reset Session
if (['/start', '/reset', 'clear', 'cancel', 'exit'].includes(lowerText)) {
  delete staticData.userStates[userId];
  return [{
    json: {
      user_id: userId,
      is_lead_flow: true,
      lead_complete: false,
      reply_type: "text",
      reply_message: "👋 Session reset! Dobara shuru karne ke liye *'card chahiye'* likhein."
    }
  }];
}

// ==============================================================
// 1️⃣ STEP 1: CATEGORY SELECTION (Lifetime Free vs Annual Fee)
// ==============================================================
const isCardIntent = lowerText.includes('card') || ['hi', 'hello'].includes(lowerText) || buttonId === 'start_card_flow';
const isMidLeadCapture = ['AWAITING_NAME', 'AWAITING_PHONE', 'AWAITING_CIBIL_CONSENT', 'AWAITING_EMAIL'].includes(userState.step);

if (isCardIntent && !isMidLeadCapture && !userState.step) {
  staticData.userStates[userId] = {
    step: 'AWAITING_FEE_CATEGORY',
    lead_data: {}
  };

  return [{
    json: {
      user_id: userId,
      is_lead_flow: true,
      lead_complete: false,
      reply_type: "interactive",
      interactive: {
        type: "button",
        body: {
          text: "💳 *Finonest Credit Card Finder*\n\nAap kis category ka card prefer karte hain?"
        },
        action: {
          buttons: [
            { type: "reply", reply: { id: "cat_lifetime_free", title: "🆓 Lifetime Free" } },
            { type: "reply", reply: { id: "cat_annual_fee", title: "💎 Annual Fee / Perks" } }
          ]
        }
      }
    }
  }];
}

// ==============================================================
// 2️⃣ STEP 2: SHOW 8 CARD TYPES (LIST MENU)
// ==============================================================
if (userState.step === 'AWAITING_FEE_CATEGORY') {
  let selectedFee = 'all';
  if (buttonId === 'cat_lifetime_free' || lowerText.includes('free')) selectedFee = 'free';
  else if (buttonId === 'cat_annual_fee' || lowerText.includes('annual')) selectedFee = 'paid';

  userState.fee_preference = selectedFee;
  userState.step = 'AWAITING_CARD_TYPE';

  return [{
    json: {
      user_id: userId,
      is_lead_flow: true,
      lead_complete: false,
      reply_type: "interactive",
      interactive: {
        type: "list",
        header: { type: "text", text: "🎯 Select Card Benefit" },
        body: { text: "Aapko kis category par sabse zyada fayda chahiye? Menu se select karein:" },
        action: {
          button: "Card Types Dekhein",
          sections: [
            {
              title: "Top Categories",
              rows: [
                { id: "type_shopping", title: "🛍️ Shopping / Cashback", description: "Amazon, Flipkart & online spends" },
                { id: "type_fuel", title: "⛽ Fuel & Petrol", description: "Surcharge waiver & fuel points" },
                { id: "type_travel", title: "✈️ Travel & Flights", description: "Airlines discount & air miles" },
                { id: "type_lounge", title: "🛋️ Lounge Access", description: "Domestic & Intl lounge visits" },
                { id: "type_dining", title: "🍽️ Dining & Food", description: "Zomato, Swiggy & restaurant offers" },
                { id: "type_upi", title: "📲 RuPay UPI Credit", description: "UPI QR scan par rewards" },
                { id: "type_rewards", title: "🎁 Rewards & Points", description: "All-rounder reward points" },
                { id: "type_utility", title: "💡 Utility & Bill Pay", description: "Electricity, recharge & utility" }
              ]
            }
          ]
        }
      }
    }
  }];
}

// ==============================================================
// 3️⃣ STEP 3: CARD TYPE RECEIVED -> ASK FULL NAME
// ==============================================================
if (userState.step === 'AWAITING_CARD_TYPE') {
  let cardType = 'shopping';
  if (buttonId.startsWith('type_')) cardType = buttonId.replace('type_', '');
  else if (lowerText.includes('fuel')) cardType = 'fuel';
  else if (lowerText.includes('travel')) cardType = 'travel';
  else if (lowerText.includes('lounge')) cardType = 'lounge';
  else if (lowerText.includes('dining')) cardType = 'dining';
  else if (lowerText.includes('upi')) cardType = 'upi';
  else if (lowerText.includes('utility')) cardType = 'utility';
  else if (lowerText.includes('reward')) cardType = 'rewards';

  userState.card_type = cardType;
  userState.step = 'AWAITING_NAME';

  return [{
    json: {
      user_id: userId,
      is_lead_flow: true,
      lead_complete: false,
      reply_type: "text",
      reply_message: "Aapke liye best cards short-list karne ke liye, kripya apna *Full Name* (as per PAN Card) enter karein:"
    }
  }];
}

// ==============================================================
// 4️⃣ STEP 4: NAME RECEIVED -> ASK MOBILE NUMBER
// ==============================================================
if (userState.step === 'AWAITING_NAME') {
  if (userText.length < 2) {
    return [{
      json: {
        user_id: userId,
        is_lead_flow: true,
        lead_complete: false,
        reply_type: "text",
        reply_message: "⚠️ Kripya apna valid *Full Name* enter karein:"
      }
    }];
  }

  userState.lead_data.name = userText;
  userState.step = 'AWAITING_PHONE';

  const detectedNumber = userId.replace(/\D/g, '').slice(-10);

  return [{
    json: {
      user_id: userId,
      is_lead_flow: true,
      lead_complete: false,
      reply_type: "text",
      reply_message: `Thanks *${userText}*!\n\nKripya apna 10-digit *Mobile Number* enter karein (ya type karein *'same'* agar yahi number \`${detectedNumber}\` use karna hai):`
    }
  }];
}

// ==============================================================
// 5️⃣ STEP 5: PHONE RECEIVED -> ASK CIBIL CHECK CONSENT
// ==============================================================
if (userState.step === 'AWAITING_PHONE') {
  let finalPhone = '';
  if (lowerText === 'same' || lowerText === 'yes') {
    finalPhone = userId.replace(/\D/g, '').slice(-10);
  } else {
    const phoneMatch = userText.match(/\b[6-9]\d{9}\b/);
    if (phoneMatch) finalPhone = phoneMatch[0];
  }

  if (!finalPhone || finalPhone.length !== 10) {
    return [{
      json: {
        user_id: userId,
        is_lead_flow: true,
        lead_complete: false,
        reply_type: "text",
        reply_message: "⚠️ *Invalid Number!* Kripya valid 10-digit mobile number enter karein ya *'same'* type karein:"
      }
    }];
  }

  userState.lead_data.phone = finalPhone;
  userState.step = 'AWAITING_CIBIL_CONSENT';

  return [{
    json: {
      user_id: userId,
      is_lead_flow: true,
      lead_complete: false,
      reply_type: "interactive",
      interactive: {
        type: "button",
        body: {
          text: `📊 *Credit Profile Verification*\n\n` +
                `👤 *Name:* ${userState.lead_data.name}\n` +
                `📱 *Mobile:* ${finalPhone}\n\n` +
                `Kya aap Finonest ko apna CIBIL/Credit Score check karne ki sehmati (consent) dete hain taaki hum 100% pre-approved cards match kar sakein?`
        },
        action: {
          buttons: [
            { type: "reply", reply: { id: "cibil_consent_agree", title: "✅ Yes, Check CIBIL" } },
            { type: "reply", reply: { id: "cibil_consent_reject", title: "❌ No, Skip CIBIL" } }
          ]
        }
      }
    }
  }];
}

// ==============================================================
// 6️⃣ STEP 6: HANDLE CIBIL CONSENT (YES vs NO)
// ==============================================================
if (userState.step === 'AWAITING_CIBIL_CONSENT') {
  if (buttonId === 'cibil_consent_agree' || lowerText === 'yes' || lowerText.includes('check')) {
    const cibilPayload = {
      name: userState.lead_data.name,
      phone: userState.lead_data.phone,
      fee_preference: userState.fee_preference,
      card_type: userState.card_type
    };

    delete staticData.userStates[userId];

    return [{
      json: {
        ...$json,
        user_id: userId,
        is_lead_flow: true,
        is_cibil_trigger: true,
        lead_info: cibilPayload
      }
    }];
  }

  if (buttonId === 'cibil_consent_reject' || lowerText === 'no' || lowerText.includes('skip')) {
    userState.step = 'AWAITING_EMAIL';
    return [{
      json: {
        user_id: userId,
        is_lead_flow: true,
        lead_complete: false,
        reply_type: "text",
        reply_message: "Koi baat nahi! Hum bina credit check ke normal offers dikha denge.\n\nKripya apna valid *Email ID* enter karein:"
      }
    }];
  }
}

// ==============================================================
// 7️⃣ STEP 7: EMAIL RECEIVED -> SAVE DATA & TRIGGER CAROUSEL
// ==============================================================
if (userState.step === 'AWAITING_EMAIL') {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(userText)) {
    return [{
      json: {
        user_id: userId,
        is_lead_flow: true,
        lead_complete: false,
        reply_type: "text",
        reply_message: "⚠️ Kripya ek valid *Email ID* enter karein (jaise: name@example.com):"
      }
    }];
  }

  userState.lead_data.email = userText;
  userState.step = 'VIEWING_CARDS';

  const savedFee = userState.fee_preference || 'all';
  const savedType = userState.card_type || 'shopping';
  const filterKey = `filter_${savedFee}_${savedType}`;

  return [{
    json: {
      ...$json,
      user_id: userId,
      button_id: filterKey,
      fee_preference: savedFee,
      card_type: savedType,
      is_lead_flow: true,
      trigger_carousel: true,
      lead_info: userState.lead_data
    }
  }];
}

// ==============================================================
// 8️⃣ STEP 8: USER CLICKS "APPLY NOW" -> TRIGGER PORTAL SUBMIT
// ==============================================================
if (buttonId.startsWith('apply_')) {
  const selectedCardId = buttonId.replace('apply_', '');

  const completedLead = {
    cardId: selectedCardId,
    applicant_name: userState.lead_data?.name || 'Customer',
    applicant_phone: userState.lead_data?.phone || userId.replace(/\D/g, '').slice(-10),
    applicant_email: userState.lead_data?.email || `${userId}@finonest.in`,
    ip_address: $json.ip_address || '157.240.199.60'
  };

  delete staticData.userStates[userId];

  return [{
    json: {
      ...$json,
      user_id: userId,
      is_lead_flow: true,
      is_final_submit: true,
      lead_complete: true,
      lead_info: completedLead
    }
  }];
}

// Default: Normal AI Agent Queries
return [{
  json: {
    ...$json,
    user_id: userId,
    is_lead_flow: false
  }
}];

